parameters.jsCode:
// O painel: o olho do Aleph-1 no centro (o estado do bot), os números de agora presos ao anel
// em volta dele e, embaixo, a linha do tempo das coletas. Tema: a Denia e o Aleph-1, do Wuthering Waves
const entrada = $input.all().map(i => i.json);
const semTabela = entrada.some(l => l.error);

// ?periodo=7d mostra a semana; o resto, as últimas 24 h
const consulta = $('Abre o painel').first().json.query ?? {};
const período = consulta.periodo === '7d' ? '7d' : '24h';
const JANELA = (período === '7d' ? 7 * 24 : 24) * 3600e3;
const agora = Date.now();
const início = agora - JANELA;

// o limite de memória do contêiner do bot (deploy.resources.limits.memory no compose.yaml)
const LIMITE_MB = 512;

// status e stats vêm com a resposta inteira e sem erro; se a API nem respondeu, vem só o erro
const corpo = nome => {
  const r = $(nome).first().json;
  return r.statusCode === 200 && r.body && typeof r.body === 'object' ? r.body : null;
};
const status = corpo('Pede o status');
const stats = corpo('Pede os stats');

const linhas = entrada
  .filter(l => l.coletado_em)
  .map(l => ({ ...l, t: new Date(l.coletado_em).getTime() }))
  .filter(l => l.t >= início && l.t <= agora + 60e3)
  .sort((a, b) => a.t - b.t);
const primeira = linhas[0];
const última = linhas.at(-1);

// ---- datas e números, no fuso do bot ----------------------------------------------------
const fuso = { timeZone: 'America/Sao_Paulo' };
const hora = t => new Date(t).toLocaleTimeString('pt-BR', { ...fuso, hour: '2-digit', minute: '2-digit' });
const dia = t => new Date(t).toLocaleDateString('pt-BR', { ...fuso, day: '2-digit', month: '2-digit' });
const diaDaSemana = t => new Date(t).toLocaleDateString('pt-BR', { ...fuso, weekday: 'short' }).replace('.', '');
const rótulo = período === '7d' ? (t => `${dia(t)} ${hora(t)}`) : hora;
const número = v => (v ?? 0).toLocaleString('pt-BR', { maximumFractionDigits: 0 });
const comUnidade = (v, unidade) => v == null ? '–' : número(v) + (unidade ? ` ${unidade}` : '');
const plural = (n, um, vários) => `${número(n)} ${n === 1 ? um : vários}`;
const local = t => Object.fromEntries(new Intl.DateTimeFormat('en-US', { ...fuso, hourCycle: 'h23', hour: '2-digit', minute: '2-digit' })
  .formatToParts(new Date(t)).map(p => [p.type, Number(p.value)]));

const duração = ms => {
  const min = Math.max(1, Math.round(ms / 60e3));
  if (min < 60) return plural(min, 'minuto', 'minutos');
  const h = Math.round(min / 60);
  return h < 48 ? plural(h, 'hora', 'horas') : plural(Math.round(h / 24), 'dia', 'dias');
};
const tempoNoAr = s => {
  const d = Math.floor(s / 86400);
  const h = Math.floor(s % 86400 / 3600);
  const m = Math.floor(s % 3600 / 60);
  return {
    curto: d ? `${d} d ${h} h` : h ? `${h} h ${m} min` : `${m} min`,
    longo: d ? `${plural(d, 'dia', 'dias')} e ${plural(h, 'hora', 'horas')}` : h ? `${plural(h, 'hora', 'horas')} e ${plural(m, 'minuto', 'minutos')}` : plural(m, 'minuto', 'minutos'),
  };
};

// ---- o estado do bot: é o que abre ou fecha o olho ------------------------------------------
const discord = status?.discord?.status;
const lavalink = status?.lavalink?.status;
const estado = !status ? 'sem-resposta' : discord !== 'connected' ? 'fora' : lavalink !== 'connected' ? 'degradado' : 'ok';
const noAr = status ? tempoNoAr(status.uptimeSeconds ?? 0) : null;
const idadeDaColeta = última ? agora - última.t : null;

const resumo = {
  ok: `no ar há ${noAr?.longo}, Discord e Lavalink conectados`,
  degradado: 'no ar, mas sem música: o Lavalink caiu',
  fora: discord === 'connecting' ? 'fora do Discord, tentando reconectar' : 'desconectado do Discord',
  'sem-resposta': 'a API do bot não respondeu ao painel',
}[estado];

// só aparece quando algo não está bem; no dia a dia o painel não tem texto corrido
const alerta = {
  'sem-resposta': ['ruim', 'A API do bot não respondeu ao painel. O contêiner pode estar parado.'],
  fora: ['ruim', discord === 'connecting' ? 'O bot caiu do Discord e está tentando reconectar.' : 'O bot está desconectado do Discord.'],
  degradado: ['atenção', `O Lavalink caiu${status?.lavalink?.since ? ` há ${duração(agora - new Date(status.lavalink.since).getTime())}` : ''}. A música parou; os outros comandos seguem respondendo.`],
}[estado] ?? (idadeDaColeta !== null && idadeDaColeta > 25 * 60e3
  ? ['atenção', `A última coleta foi há ${duração(idadeDaColeta)}. Confira se o fluxo AlephBot · Histórico de stats está publicado.`]
  : null);

const estadoDe = s => s === 'connected' ? 'bom' : s === 'connecting' ? 'atenção' : 'ruim';
const estadoDiscord = status ? estadoDe(discord) : 'ruim';
const estadoLavalink = status ? estadoDe(lavalink) : 'ruim';
const PALAVRA = { bom: 'conectado', atenção: 'reconectando', ruim: 'caído' };

// ---- os números de agora: ao vivo pela API; sem ela, a última coleta ------------------------
const agoraÉ = {
  servidores: stats?.guilds ?? última?.servidores,
  membros: stats?.members ?? última?.membros,
  online: stats?.online ?? última?.online,
  tocando: stats?.music?.playing ?? última?.tocando,
  players: stats?.music?.players ?? última?.players,
  fila: stats?.music?.queuedTracks ?? última?.na_fila,
  memória: stats?.memory?.workingSetMb ?? última?.memoria_mb,
};
const nomeDoPeríodo = período === '7d' ? '7 dias' : '24 h';

// a cor da variação só vale onde subir é bom; o resto muda sem julgamento
const variação = (campo, valor) => {
  if (!primeira || valor == null) return { texto: 'sem coletas no período', classe: '' };
  const d = valor - (primeira[campo] ?? 0);
  if (d === 0) return { texto: `estável em ${nomeDoPeríodo}`, classe: '' };
  return { texto: `${d > 0 ? '+' : '−'}${número(Math.abs(d))} em ${nomeDoPeríodo}`, classe: d > 0 ? 'subiu' : 'desceu' };
};
const pico = linhas.reduce((m, l) => (l.online ?? 0) > (m?.online ?? -1) ? l : m, null);
const contextoOnline = pico
  ? `pico de ${número(pico.online)} ${período === '7d' ? `em ${dia(pico.t)}` : `às ${hora(pico.t)}`}`
  : 'pessoas, sem contar bots';

const ocupação = agoraÉ.memória == null ? 0 : Math.min(100, Math.round(agoraÉ.memória / LIMITE_MB * 100));
const gravidade = ocupação >= 90 ? 'ruim' : ocupação >= 75 ? 'atenção' : 'normal';
const SEGMENTOS = 20;
const medidor = `<div class="medidor ${gravidade}" role="meter" aria-valuemin="0" aria-valuemax="${LIMITE_MB}" aria-valuenow="${Math.round(agoraÉ.memória ?? 0)}" aria-label="Memória do bot">${Array.from({ length: SEGMENTOS }, (_, i) => `<i${i < Math.round(ocupação / 100 * SEGMENTOS) ? ' class="cheio"' : ''}></i>`).join('')}</div>`;

const vServidores = variação('servidores', agoraÉ.servidores);
const vMembros = variação('membros', agoraÉ.membros);
const ping = status?.discord?.latencyMs;

// ---------------------------------------------------------------------------------------
// as peças do tema: céu, anéis, olho e bolhas são sempre o mesmo desenho
// ---------------------------------------------------------------------------------------
const PALCO = { larg: 1440, alt: 600, cx: 720, cy: 300, anel: 460 };
const OLHO = 1.12;

// O céu: nebulosa de ruído fractal presa numa faixa que desce do olho até a esquerda, como uma
// Via Láctea; poeira escura por cima pra dar fundo; estrelas juntas na faixa e raras fora dela
function céu() {
  let s = 2024;
  const r = () => (s = (s * 16807) % 2147483647) / 2147483647;
  const normal = () => (r() + r() + r() + r() - 2) / 1.15;
  const [ax, ay, bx, by] = [1500, 20, -60, 820];
  const comprimento = Math.hypot(bx - ax, by - ay);
  const [ux, uy] = [(bx - ax) / comprimento, (by - ay) / comprimento];
  const [nx, ny] = [-uy, ux];
  const estrelas = [];
  for (let k = 0; k < 340; k++) {
    const t = r() * comprimento;
    const d = r() < .78 ? normal() * 150 : (r() - .5) * 1600;
    const x = ax + ux * t + nx * d;
    const y = ay + uy * t + ny * d;
    if (x < 0 || x > 1440 || y < 0 || y > 900) continue;
    const q = r();
    const raio = q < .8 ? .3 + r() * .35 : q < .97 ? .65 + r() * .45 : 1.1 + r() * .6;
    const o = q < .8 ? .2 + r() * .45 : .55 + r() * .4;
    estrelas.push(`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${raio.toFixed(2)}" opacity="${o.toFixed(2)}"/>`);
    if (q >= .97) estrelas.push(`<circle class="halo" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${(raio * 3).toFixed(1)}"/>`);
  }
  const ângulo = Math.atan2(ay - by, ax - bx) * -180 / Math.PI;
  const nuvem = (id, semente, freq, [cr, cg, cb], ganho, corte) => `<filter id="${id}" x="0" y="0" width="100%" height="100%" color-interpolation-filters="sRGB">
        <feTurbulence type="fractalNoise" baseFrequency="${freq}" numOctaves="5" seed="${semente}"/>
        <feColorMatrix values="0 0 0 0 ${cr}  0 0 0 0 ${cg}  0 0 0 0 ${cb}  ${ganho} 0 0 0 ${corte}"/>
      </filter>`;
  return `<div class="ceu" aria-hidden="true">
    <svg viewBox="0 0 1440 900" preserveAspectRatio="xMidYMid slice">
      <defs>
      ${nuvem('nebula-azul', 7, '0.0019 0.0031', [.52, .62, .98], 3.1, -1.5)}
      ${nuvem('nebula-rosa', 19, '0.0026 0.0038', [.93, .58, .76], 3.4, -1.85)}
      ${nuvem('nebula-poeira', 3, '0.0042 0.0058', [.01, .01, .04], 2.6, -1.25)}
      <linearGradient id="faixa-largura" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset=".5" stop-color="#fff"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>
      <mask id="faixa" maskUnits="userSpaceOnUse" x="0" y="0" width="1440" height="900">
        <rect x="-600" y="${((ay + by) / 2 - 300).toFixed(0)}" width="2640" height="600" fill="url(#faixa-largura)" transform="rotate(${ângulo.toFixed(1)} 720 ${((ay + by) / 2).toFixed(0)})"/>
      </mask>
      </defs>
      <g class="nebulosa" mask="url(#faixa)">
        <rect class="azul" width="1440" height="900" filter="url(#nebula-azul)"/>
        <rect class="rosa" width="1440" height="900" filter="url(#nebula-rosa)"/>
        <rect class="poeira" width="1440" height="900" filter="url(#nebula-poeira)"/>
      </g>
      <g class="estrelas">${estrelas.join('')}</g>
    </svg>
  </div>
  <div class="grao" aria-hidden="true"></div>`;
}

// os anéis em volta do olho, como um astrolábio: finos, com marcas de grau no de ouro
function anéis() {
  const marcas = Array.from({ length: 72 }, (_, i) => {
    const â = i * 5 * Math.PI / 180;
    const [r1, r2] = i % 6 === 0 ? [452, 470] : [458, 464];
    return `<line x1="${(800 + r1 * Math.cos(â)).toFixed(1)}" y1="${(800 + r1 * Math.sin(â)).toFixed(1)}" x2="${(800 + r2 * Math.cos(â)).toFixed(1)}" y2="${(800 + r2 * Math.sin(â)).toFixed(1)}"/>`;
  }).join('');
  return `<svg class="aneis" viewBox="0 0 1600 1600" aria-hidden="true">
          <circle cx="800" cy="800" r="300"/>
          <circle cx="800" cy="800" r="460" class="forte"/>
          <circle cx="800" cy="800" r="640"/>
          <circle cx="800" cy="800" r="790" class="tracejado"/>
          <g class="marcas">${marcas}</g>
          <line x1="0" y1="800" x2="1600" y2="800" class="eixo"/>
        </svg>`;
}

// uma bolha da Denia: miolo transparente, aro furta-cor e o reflexo da luz
const bolha = (tamanho, onde, atraso = 0) => `<svg class="bolha" viewBox="0 0 100 100" style="width:${tamanho}px;${onde};animation-delay:${atraso}s" aria-hidden="true">
          <circle cx="50" cy="50" r="46" fill="url(#bolha-miolo)" stroke="url(#bolha-aro)" stroke-width="2.2"/>
          <path d="M24 38A30 30 0 0 1 44 20" fill="none" stroke="#fff" stroke-opacity=".85" stroke-width="4.5" stroke-linecap="round"/>
          <circle cx="71" cy="70" r="3.2" fill="#fff" fill-opacity=".5"/>
        </svg>`;

// o olho do Aleph-1: um eclipse dentro de pálpebras de luz. Aberto, o bot está de pé; com o
// brilho apagado, está sem música; fechado, caiu ou não responde
function olho() {
  const aberto = estado === 'ok' || estado === 'degradado';
  let s = 77;
  const r = () => (s = (s * 16807) % 2147483647) / 2147483647;
  const poeira = Array.from({ length: 34 }, () => {
    const â = r() * 2 * Math.PI;
    const d = Math.sqrt(r()) * 96;
    return `<circle cx="${(247 + d * Math.cos(â)).toFixed(1)}" cy="${(181 + d * Math.sin(â)).toFixed(1)}" r="${(.4 + r() * .9).toFixed(2)}" opacity="${(.15 + r() * .45).toFixed(2)}"/>`;
  }).join('');
  const pálpebras = aberto
    ? `<path class="palpebra" d="M14 170Q260 -26 506 170"/><path class="palpebra" d="M14 170Q260 366 506 170"/>
        <path class="palpebra fina" d="M2 170Q260 -52 518 170"/><path class="palpebra fina" d="M2 170Q260 392 518 170"/>`
    : `<path class="palpebra" d="M14 170Q260 214 506 170"/><path class="palpebra fina" d="M2 170Q260 236 518 170"/>`;
  const rótulo = {
    ok: 'O olho do Aleph-1, aberto: o bot está no ar',
    degradado: 'O olho do Aleph-1, com o brilho apagado: o bot está no ar sem música',
    fora: 'O olho do Aleph-1, fechado: o bot caiu do Discord',
    'sem-resposta': 'O olho do Aleph-1, fechado: o bot não responde',
  }[estado];
  return `<svg class="olho${aberto ? '' : ' fechado'}${estado === 'degradado' ? ' degradado' : ''}" viewBox="0 0 520 340" role="img" aria-label="${rótulo}">
          <defs>
            <radialGradient id="olho-coroa"><stop offset="0" stop-color="var(--olho-brilho)" stop-opacity=".55"/><stop offset=".42" stop-color="var(--olho-brilho)" stop-opacity=".16"/><stop offset="1" stop-color="var(--olho-brilho)" stop-opacity="0"/></radialGradient>
            <radialGradient id="olho-aro" cx="64%" cy="34%" r="66%"><stop offset="0" stop-color="#fff"/><stop offset=".5" stop-color="var(--olho-nucleo)"/><stop offset=".78" stop-color="var(--olho-brilho)"/><stop offset="1" stop-color="var(--olho-rosa)"/></radialGradient>
            <linearGradient id="olho-palpebra" x1="0" x2="1"><stop offset="0" stop-color="var(--olho-rosa)" stop-opacity="0"/><stop offset=".22" stop-color="var(--olho-rosa)" stop-opacity=".75"/><stop offset=".5" stop-color="var(--olho-nucleo)"/><stop offset=".78" stop-color="var(--olho-brilho)" stop-opacity=".75"/><stop offset="1" stop-color="var(--olho-brilho)" stop-opacity="0"/></linearGradient>
            <linearGradient id="olho-raio" x1="0" x2="1"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset=".5" stop-color="#fff" stop-opacity=".9"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>
            <filter id="olho-desfoque" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="7"/></filter>
            <clipPath id="olho-abertura"><path d="M14 170Q260 -26 506 170Q260 366 14 170Z"/></clipPath>
          </defs>
          <circle class="coroa" cx="260" cy="170" r="210" fill="url(#olho-coroa)"/>
          <g class="iris" clip-path="url(#olho-abertura)">
            <circle class="anel-marcas" cx="260" cy="170" r="150" fill="none"/>
            <circle cx="260" cy="170" r="124" fill="url(#olho-aro)" filter="url(#olho-desfoque)" opacity=".9"/>
            <circle class="anel-fora" cx="260" cy="170" r="128" fill="none"/>
            <circle cx="260" cy="170" r="116" fill="url(#olho-aro)"/>
            <circle class="pupila" cx="247" cy="181" r="107"/>
            <g class="poeira">${poeira}</g>
            <circle class="anel-dentro" cx="247" cy="181" r="76" fill="none"/>
            <circle class="anel-dentro" cx="247" cy="181" r="44" fill="none"/>
          </g>
          ${pálpebras}
          <rect class="raio" x="96" y="96.5" width="420" height="1.4" fill="url(#olho-raio)"/>
          <path class="faisca" d="M338 97C340 95 340 95 352 97C340 99 340 99 338 109C336 99 336 99 324 97C336 95 336 95 338 85Z"/>
        </svg>`;
}

// a escrita de Lahai-Roi, a região dela, só tem letras sem acento; é ornamento, fora da leitura
const escrita = texto => `<span class="escrita" aria-hidden="true">${texto.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9 -]/g, '')}</span>`;

// "Threnodian do Vazio, Aleph-1": o título dele no jogo, gravado no anel em volta do olho
const RAIO = 306;
const inscrição = `<svg class="inscricao" viewBox="0 0 700 700" aria-hidden="true"><defs><path id="anel-escrita" d="M${350 - RAIO} 350a${RAIO} ${RAIO} 0 1 1 ${2 * RAIO} 0a${RAIO} ${RAIO} 0 1 1 ${-2 * RAIO} 0"/></defs><text><textPath href="#anel-escrita" textLength="${(2 * Math.PI * RAIO - 6).toFixed(0)}" lengthAdjust="spacing">${'THRENODIAN OF THE VOID ALEPH ONE DENIA '.repeat(4)}</textPath></text></svg>`;

const ÍCONE = {
  bom: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 8.5l3 3 6-7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  atenção: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 2.5l6 11H2z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M8 6.5v3.2M8 11.6v.1" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>',
  ruim: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>',
  relógio: '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6" fill="none" stroke="currentColor" stroke-width="1.4"/><path d="M8 4.6V8l2.4 1.6" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>',
};

// o grão de filme: um ladrilho de ruído que se repete
const GRÃO = `url("data:image/svg+xml,${encodeURIComponent(`<svg xmlns='http://www.w3.org/2000/svg' width='240' height='240'><filter id='g'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='240' height='240' filter='url(#g)'/></svg>`)}")`;

// ---------------------------------------------------------------------------------------
// o palco: os números de agora, presos ao anel de ouro em volta do olho
// ---------------------------------------------------------------------------------------
const leituras = [
  { ângulo: 160, rótulo: 'Servidores', valor: agoraÉ.servidores, contexto: vServidores.texto, classe: vServidores.classe },
  { ângulo: 180, rótulo: 'Membros', valor: agoraÉ.membros, contexto: vMembros.texto, classe: vMembros.classe },
  { ângulo: 200, rótulo: 'Online agora', valor: agoraÉ.online, contexto: contextoOnline },
  { ângulo: 20, rótulo: 'Ping do Discord', valor: ping, unidade: 'ms', contexto: ping == null ? 'sem conexão' : 'latência do gateway' },
  { ângulo: 0, rótulo: 'Tocando agora', valor: agoraÉ.tocando, contexto: agoraÉ.players == null ? 'sem dados' : !agoraÉ.players ? 'nenhum player aberto' : `de ${plural(agoraÉ.players, 'player', 'players')}, ${número(agoraÉ.fila)} na fila` },
  { ângulo: -20, rótulo: 'Memória', valor: agoraÉ.memória, unidade: 'MB', contexto: agoraÉ.memória == null ? 'sem dados' : `${ocupação}% do limite de ${LIMITE_MB} MB`, extra: agoraÉ.memória == null ? '' : medidor },
].map(l => {
  const θ = l.ângulo * Math.PI / 180;
  return { ...l, x: PALCO.cx + PALCO.anel * Math.cos(θ), y: PALCO.cy - PALCO.anel * Math.sin(θ), lado: Math.cos(θ) < 0 ? -1 : 1 };
});

const ligações = `<svg class="ligacoes" viewBox="0 0 ${PALCO.larg} ${PALCO.alt}" aria-hidden="true">${leituras.map(l => `
          <circle class="no-halo" cx="${l.x.toFixed(1)}" cy="${l.y.toFixed(1)}" r="9"/>
          <line x1="${(l.x + l.lado * 7).toFixed(1)}" y1="${l.y.toFixed(1)}" x2="${(l.x + l.lado * 36).toFixed(1)}" y2="${l.y.toFixed(1)}"/>
          <circle class="no" cx="${l.x.toFixed(1)}" cy="${l.y.toFixed(1)}" r="3.5"/>`).join('')}
        </svg>`;

// o meio do número fica na altura do nó
const blocos = leituras.map(l => `
        <div class="leitura ${l.lado < 0 ? 'esq' : 'dir'}" style="${l.lado < 0 ? `right:${(PALCO.larg - l.x + 46).toFixed(0)}px` : `left:${(l.x + 46).toFixed(0)}px`};top:${(l.y - 51).toFixed(0)}px">
          <p class="leitura-rotulo">${l.rótulo}</p>
          <p class="leitura-valor">${l.valor == null ? '–' : número(l.valor)}${l.unidade && l.valor != null ? `<small>${l.unidade}</small>` : ''}</p>${l.extra ? `
          ${l.extra}` : ''}
          <p class="leitura-contexto${l.classe ? ` ${l.classe}` : ''}">${l.contexto}</p>
        </div>`).join('');

// ---------------------------------------------------------------------------------------
// a linha do tempo: três trilhas com o mesmo eixo de horas; x é a hora da coleta, não a posição
// ---------------------------------------------------------------------------------------
function escalaDaTrilha(máximo, inteiro) {
  const alvo = Math.max(máximo * 1.08, inteiro ? 2 : 1);
  const bruto = alvo / 3;
  const ordem = 10 ** Math.floor(Math.log10(bruto));
  let passo = [1, 2, 2.5, 5, 10].map(f => f * ordem).find(p => p >= bruto);
  if (inteiro) passo = Math.max(1, Math.round(passo));
  const topo = Math.ceil(alvo / passo) * passo;
  const marcas = [];
  for (let v = 0; v <= topo + 1e-9; v += passo) marcas.push(v);
  return { topo, marcas };
}

const fração = t => (t - início) / JANELA;
// mais de 35 min sem coleta (duas perdidas) vira buraco na linha, não reta inventada
const BURACO = 35 * 60e3;

const trilhas = [
  { id: 'pessoas', nome: 'Pessoas', alt: 150, inteiro: true, séries: [['Membros', 'membros'], ['Online', 'online']] },
  { id: 'musica', nome: 'Música', alt: 96, inteiro: true, séries: [['Players abertos', 'players'], ['Tocando', 'tocando']] },
  { id: 'memoria', nome: 'Memória', alt: 132, unidade: 'MB', limite: LIMITE_MB, séries: [['Processo', 'memoria_mb'], ['Heap do .NET', 'heap_mb']] },
].map(t => {
  const séries = t.séries.map(([nome, campo]) => ({ nome, valores: linhas.map(l => l[campo] ?? null) }));
  const valores = séries.flatMap(s => s.valores).filter(v => v != null);
  return { ...t, ...escalaDaTrilha(Math.max(0, ...valores, t.limite ?? 0), t.inteiro), séries };
});

const trilha = t => {
  const x = i => fração(linhas[i].t) * 1000;
  const y = v => t.alt - v / t.topo * t.alt;
  const pct = v => v / t.topo * 100;
  const caminho = valores => {
    let d = '';
    let aberto = false;
    valores.forEach((v, i) => {
      if (v == null || (i > 0 && linhas[i].t - linhas[i - 1].t > BURACO)) aberto = false;
      if (v == null) return;
      d += `${aberto ? 'L' : 'M'}${x(i).toFixed(1)} ${y(v).toFixed(1)}`;
      aberto = true;
    });
    return d;
  };
  const último = valores => { let i = valores.length - 1; while (i >= 0 && valores[i] == null) i--; return i; };
  return `
      <div class="trilha" data-trilha="${t.id}" style="--alt:${t.alt}px">
        <div class="trilha-rotulo">
          <h3 class="titulo">${t.nome}${escrita(t.nome)}</h3>
          <ul>${t.séries.map((s, k) => `
            <li><span class="chave s${k + 1}"></span><span class="nome">${s.nome}</span><b data-valor="${t.id}-${k}">${comUnidade(s.valores[último(s.valores)], t.unidade)}</b></li>`).join('')}
          </ul>
        </div>
        <div class="trilha-plot" role="img" aria-label="${t.nome}: ${t.séries.map(s => s.nome).join(' e ')} ao longo do período. Os números estão na tabela.">
          <svg viewBox="0 0 1000 ${t.alt}" preserveAspectRatio="none" aria-hidden="true">
            <g class="grade">${t.marcas.map(v => `<line x1="0" x2="1000" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/>`).join('')}</g>${t.limite == null ? '' : `
            <line class="limite" x1="0" x2="1000" y1="${y(t.limite).toFixed(1)}" y2="${y(t.limite).toFixed(1)}"/>`}${t.séries.map((s, k) => `
            <path class="serie s${k + 1}" d="${caminho(s.valores)}"/>`).join('')}
          </svg>${t.limite == null ? '' : `
          <span class="rotulo-limite" style="bottom:${pct(t.limite).toFixed(2)}%">limite de ${número(t.limite)} ${t.unidade}</span>`}${t.séries.map((s, k) => {
            const i = último(s.valores);
            return i < 0 ? '' : `
          <span class="ponta s${k + 1}" style="left:${(x(i) / 10).toFixed(2)}%;bottom:${pct(s.valores[i]).toFixed(2)}%"></span>`;
          }).join('')}${t.séries.map((_, k) => `
          <span class="marcador s${k + 1}" aria-hidden="true"></span>`).join('')}
        </div>
        <div class="ticks-y" aria-hidden="true">${t.marcas.map(v => `<span style="bottom:${pct(v).toFixed(2)}%">${número(v)}</span>`).join('')}</div>
      </div>`;
};

// as marcas do eixo: de 4 em 4 horas nas 24 h, na virada do dia nos 7 dias, no relógio do bot
const marcasDoEixo = [];
for (let t = Math.ceil(início / (15 * 60e3)) * 15 * 60e3; t < agora; t += 15 * 60e3) {
  const { hour, minute } = local(t);
  if (minute !== 0) continue;
  if (período === '7d' ? hour === 0 : hour % 4 === 0) marcasDoEixo.push({ t, texto: período === '7d' ? `${diaDaSemana(t)} ${dia(t).slice(0, 2)}` : hora(t) });
}
const eixo = `
    <div class="tempo-eixo" aria-hidden="true"><div>${marcasDoEixo.filter(m => fração(m.t) > .03 && fração(m.t) < .95).map(m => `<span${fração(m.t) > .86 ? ' class="perto"' : ''} style="left:${(fração(m.t) * 100).toFixed(2)}%">${m.texto}</span>`).join('')}<span class="agora" style="left:100%">agora</span></div></div>`;

const vazio = semTabela
  ? 'Ainda não há onde ler: a tabela <code>aleph_stats</code> nasce na primeira coleta do fluxo <strong>AlephBot · Histórico de stats</strong>.'
  : `Nenhuma coleta ${período === '7d' ? 'nos últimos 7 dias' : 'nas últimas 24 horas'}. O fluxo <strong>AlephBot · Histórico de stats</strong> grava uma a cada 15 minutos: confira se ele está publicado.`;

// o JSON vai dentro de um <script>: sem "<" cru, nada dele fecha a tag antes da hora
const dados = JSON.stringify({
  frações: linhas.map(l => +fração(l.t).toFixed(5)),
  rótulos: linhas.map(l => rótulo(l.t)),
  agora: última ? `última coleta, ${rótulo(última.t)}` : '',
  trilhas: Object.fromEntries(trilhas.map(t => [t.id, { topo: t.topo, unidade: t.unidade ?? '', séries: t.séries.map(s => s.valores) }])),
}).replace(/</g, '\\u003c');

const colunas = ['Quando', 'Servidores', 'Membros', 'Online', 'Players', 'Tocando', 'Na fila', 'Memória (MB)', 'Heap (MB)'];
const tabela = [...linhas].reverse().map(l => `
            <tr><th scope="row">${rótulo(l.t)}</th>${['servidores', 'membros', 'online', 'players', 'tocando', 'na_fila', 'memoria_mb', 'heap_mb'].map(c => `<td>${número(l[c])}</td>`).join('')}</tr>`).join('');

const ficha = status
  ? [
    `AlephBot ${status.version}`,
    String(status.runtime ?? '').replace(/^(\.NET \d+)\..*$/, '$1'),
    status.mode === 'production' ? 'produção' : 'desenvolvimento',
    `no ar desde ${dia(new Date(status.startedAt).getTime())} às ${hora(new Date(status.startedAt).getTime())}`,
    ...(status.lavalink?.stats ? [`Lavalink com CPU ${Math.round(status.lavalink.stats.cpuLoad * 100)}% e ${número(status.lavalink.stats.memoryUsedMb)} MB`] : []),
  ]
  : ['A API do bot não respondeu'];

