  .trilha { display: grid; grid-template-columns: 230px minmax(0, 1fr) 48px; align-items: start; padding: 24px 0; }
  .trilha + .trilha { border-top: 1px solid var(--fio); }
  .trilha-rotulo h3 { margin: -6px 0 16px; font-size: 30px; line-height: .95; }
  .trilha-rotulo h3 .escrita { margin-top: 7px; font-size: 9px; }
  .trilha-rotulo ul { display: grid; gap: 7px; max-width: 190px; margin: 0; padding: 0; list-style: none; }
  .trilha-rotulo li { display: grid; grid-template-columns: 14px 1fr auto; align-items: center; gap: 10px; font-size: 15px; color: var(--tinta-2); }
  .trilha-rotulo b { font-size: 17px; font-weight: 600; color: var(--tinta); font-variant-numeric: tabular-nums; }
  .chave { width: 14px; height: 2px; border-radius: 1px; }
  .chave.s1 { background: var(--s1); }
  .chave.s2 { background: var(--s2); }
  .trilha-plot { position: relative; height: var(--alt); cursor: crosshair; }
  .trilha-plot svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .trilha-plot .grade line { stroke: var(--grade); stroke-width: 1; vector-effect: non-scaling-stroke; }
  .trilha-plot .limite { stroke: var(--apagado); stroke-width: 1; stroke-dasharray: 5 5; vector-effect: non-scaling-stroke; opacity: .8; }
  .trilha-plot .serie { fill: none; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; vector-effect: non-scaling-stroke; }
  .trilha-plot .serie.s1 { stroke: var(--s1); filter: drop-shadow(0 0 3px color-mix(in srgb, var(--s1) 40%, transparent)); }
  .trilha-plot .serie.s2 { stroke: var(--s2); filter: drop-shadow(0 0 3px color-mix(in srgb, var(--s2) 40%, transparent)); }
  .rotulo-limite { position: absolute; right: 6px; transform: translateY(-5px); font-size: 12px; color: var(--apagado); }
  .ponta, .marcador { position: absolute; width: 10px; height: 10px; margin: 0 0 -5px -5px; border-radius: 50%; border: 2px solid var(--fundo-2); }
  .ponta.s1, .marcador.s1 { background: var(--s1); }
  .ponta.s2, .marcador.s2 { background: var(--s2); }
  .marcador { display: none; z-index: 2; }
  .ticks-y { position: relative; height: var(--alt); }
  .ticks-y span { position: absolute; left: 12px; transform: translateY(50%); font-size: 12px; line-height: 1; color: var(--apagado); font-variant-numeric: tabular-nums; }
  .tempo-eixo { display: grid; grid-template-columns: 230px minmax(0, 1fr) 48px; height: 30px; border-top: 1px solid var(--fio); }
  .tempo-eixo > div { grid-column: 2; position: relative; }
  .tempo-eixo span { position: absolute; top: 9px; transform: translateX(-50%); font-size: 12px; line-height: 1; color: var(--apagado); font-variant-numeric: tabular-nums; white-space: nowrap; }
  .tempo-eixo span.agora { transform: translateX(-100%); color: var(--tinta-2); }
  .tempo-mira { position: absolute; top: 18px; bottom: 0; width: 1px; display: none; pointer-events: none; background: linear-gradient(180deg, transparent, var(--eixo) 6%, var(--eixo) 96%, transparent); }
  .vazio { max-width: 64ch; margin: 0; padding: 28px 0 8px; color: var(--tinta-2); }
  code { font-size: .95em; }

  /* ---- o rodapé: a ficha do bot e todos os números ---- */
  .rodape { z-index: 1; display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 16px 32px; margin-top: 36px; padding-top: 16px; border-top: 1px solid var(--fio); }
  .numeros { flex: 1 1 100%; order: 2; }
  summary { cursor: pointer; width: max-content; font-size: 14px; font-weight: 500; color: var(--tinta-2); }
  summary:hover { color: var(--tinta); }
  .rolagem { max-height: 420px; overflow: auto; margin-top: 14px; }
  table { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; }
  th, td { padding: 8px 12px; text-align: right; border-bottom: 1px solid var(--grade); white-space: nowrap; }
  th:first-child { text-align: left; }
  thead th { position: sticky; top: 0; background: var(--fundo-2); color: var(--tinta-2); font-weight: 500; }
  tbody th { font-weight: 400; color: var(--tinta-2); }
  .ficha { display: flex; flex-wrap: wrap; gap: 6px 0; margin: 0; padding: 0; list-style: none; font-size: 12px; color: var(--apagado); }
  .ficha li + li::before { content: ""; display: inline-block; width: 4px; height: 4px; margin: 0 12px 2px; background: var(--ouro); opacity: .7; transform: rotate(45deg); }

  @media (max-width: 1439px) { .palco { --k: .9; } }
  @media (max-width: 1299px) { .palco { --k: .8; } }
  @media (max-width: 1159px) { .palco { --k: .7; } }
  @media (max-width: 1019px) {
    .palco { height: auto; }
    .palco-tela { position: relative; left: auto; width: auto; height: auto; transform: none; display: grid; grid-template-columns: 1fr 1fr; gap: 24px 20px; padding-top: 300px; }
    .reticula, .aneis, .inscricao, .ligacoes, .palco-tela .bolha { display: none; }
    .olho { left: 50%; top: -20px; width: 440px; height: 288px; transform: translateX(-50%); }
    .leitura { position: static; width: auto; text-align: left !important; }
    .leitura.esq .medidor { margin-left: 0; }
    .leitura-valor { font-size: 40px; }
    .alerta { position: static; transform: none; grid-column: 1 / -1; white-space: normal; }
    .estado-olho { position: static; transform: none; grid-column: 1 / -1; grid-row: 1; flex-wrap: wrap; white-space: normal; }
    .trilha { grid-template-columns: 1fr 40px; }
    .trilha-rotulo { grid-column: 1 / -1; margin-bottom: 12px; }
    .trilha-rotulo ul { display: flex; flex-wrap: wrap; gap: 6px 20px; max-width: none; }
    .tempo-eixo { grid-template-columns: 1fr 40px; }
    .tempo-eixo > div { grid-column: 1; }
  }
  @media (max-width: 640px) {
    .tempo-eixo span.perto { display: none; }
    .raiz { padding: 20px 16px 40px; }
    .topo { flex-direction: column; align-items: flex-start; }
    .topo-dir { width: 100%; justify-content: space-between; }
    .palco-tela { padding-top: 220px; }
    .olho { width: 320px; height: 209px; }
  }
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation: none !important; }
  }
</style>
</head>
<body>
<div class="raiz">
<svg width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false">
  <defs>
    <radialGradient id="bolha-miolo" cx="50%" cy="50%" r="50%"><stop offset=".62" stop-color="#fff" stop-opacity="0"/><stop offset=".9" stop-color="var(--olho-brilho)" stop-opacity=".14"/><stop offset="1" stop-color="var(--olho-rosa)" stop-opacity=".28"/></radialGradient>
    <linearGradient id="bolha-aro" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="var(--olho-rosa)"/><stop offset=".35" stop-color="#9fe3ff"/><stop offset=".65" stop-color="var(--olho-brilho)"/><stop offset="1" stop-color="#f3d58a"/></linearGradient>
  </defs>
</svg>
  ${céu()}
  <header class="topo">
    <a class="marca" href="?periodo=${período}"><svg viewBox="0 0 30 20" aria-hidden="true"><path d="M1 10Q15 -2 29 10Q15 22 1 10Z" fill="none" stroke="var(--ouro)" stroke-width="1.3"/><circle cx="15" cy="10" r="4.2" fill="none" stroke="var(--ouro)" stroke-width="1.3"/><circle cx="14" cy="11" r="2.2" fill="var(--ouro)"/></svg><span class="titulo">AlephBot${escrita('AlephBot')}</span></a>
    <div class="topo-dir">
      <p class="atualizado">Atualizado às ${hora(agora)}</p>
      <nav class="periodo" aria-label="Período">
        <a href="?periodo=24h"${período === '24h' ? ' aria-current="page"' : ''}>24 horas</a>
        <a href="?periodo=7d"${período === '7d' ? ' aria-current="page"' : ''}>7 dias</a>
      </nav>
    </div>
  </header>

  <main>
  <section class="palco" aria-labelledby="t-agora">
    <h1 id="t-agora" class="sr">AlephBot: ${resumo}</h1>
    <div class="palco-tela">
      <div class="reticula" aria-hidden="true"></div>
      ${anéis()}
      ${inscrição}
      ${olho()}
      ${bolha(46, `left:${PALCO.cx - 290}px;top:${PALCO.cy + 34}px`, 0)}
      ${bolha(28, `left:${PALCO.cx + 212}px;top:${PALCO.cy - 178}px`, -4)}
      ${bolha(18, `left:${PALCO.cx + 250}px;top:${PALCO.cy + 100}px`, -9)}
      ${bolha(14, `left:${PALCO.cx - 224}px;top:${PALCO.cy - 168}px`, -6)}
      ${alerta ? `<p class="alerta ${alerta[0]}" role="alert">${ÍCONE[alerta[0]]}${alerta[1]}</p>` : ''}
      ${ligações}${blocos}
      <ul class="estado-olho">
        <li class="${estadoDiscord}">${ÍCONE[estadoDiscord]}Discord<span class="sr"> ${PALAVRA[estadoDiscord]}</span></li>
        <li class="${estadoLavalink}">${ÍCONE[estadoLavalink]}Lavalink<span class="sr"> ${PALAVRA[estadoLavalink]}</span></li>${noAr ? `
        <li class="no-ar">${ÍCONE.relógio}${noAr.curto} no ar</li>` : ''}
      </ul>
    </div>
  </section>

  <section class="tempo" aria-labelledby="t-tempo">
    <header class="tempo-topo">
      <h2 id="t-tempo" class="titulo">${período === '7d' ? 'Últimos 7 dias' : 'Últimas 24 horas'}${escrita(período === '7d' ? 'ultimos sete dias' : 'ultimas vinte e quatro horas')}</h2>
      <p class="tempo-hora" aria-live="polite" data-hora>${última ? `última coleta, ${rótulo(última.t)}` : ''}</p>
    </header>${linhas.length === 0 ? `
    <p class="vazio">${vazio}</p>` : `
    <p class="sr" aria-live="polite" data-leitura></p>
    <div class="trilhas" data-trilhas role="group" tabindex="0" aria-label="Linha do tempo. Use as setas para andar pelas coletas.">${trilhas.map(trilha).join('')}
      <span class="tempo-mira" aria-hidden="true"></span>
    </div>${eixo}`}
  </section>
  </main>

  <footer class="rodape">
    <ul class="ficha">${ficha.map(f => `
      <li>${f}</li>`).join('')}
    </ul>${linhas.length === 0 ? '' : `
    <details class="numeros">
      <summary>Todos os números</summary>
      <div class="rolagem">
        <table>
          <caption class="sr">Todas as coletas do período, da mais nova para a mais antiga</caption>
          <thead><tr>${colunas.map(c => `<th scope="col">${c}</th>`).join('')}</tr></thead>
          <tbody>${tabela}
          </tbody>
        </table>
      </div>
    </details>`}
  </footer>
<script>
  // a página se recarrega a cada 5 minutos, menos enquanto alguém usa a linha do tempo ou a tabela
  setInterval(() => {
    const ocupada = document.querySelector('details[open]') || document.activeElement?.closest?.('[data-trilhas]');
    if (!document.hidden && !ocupada) location.reload();
  }, 5 * 60e3);
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) document.querySelectorAll('svg').forEach(s => s.pauseAnimations?.());
</script>${linhas.length === 0 ? '' : `
<script>
  // a mira corre pelas três trilhas juntas e acha a coleta mais perto; os valores ao lado mostram ela
  (() => {
    const dados = ${dados};
    const n = dados.frações.length;
    const caixa = document.querySelector('[data-trilhas]');
    const mira = caixa.querySelector('.tempo-mira');
    const hora = document.querySelector('[data-hora]');
    const plots = [...caixa.querySelectorAll('.trilha-plot')];
    const fmt = (v, u) => v == null ? '–' : Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 0 }) + (u ? ' ' + u : '');
    const maisPerto = f => {
      let lo = 0, hi = n - 1;
      while (hi - lo > 1) { const m = (lo + hi) >> 1; if (dados.frações[m] < f) lo = m; else hi = m; }
      return Math.abs(dados.frações[lo] - f) <= Math.abs(dados.frações[hi] - f) ? lo : hi;
    };
    let atual = null;
    const mostrar = i => {
      atual = i;
      const p0 = plots[0].getBoundingClientRect();
      const c = caixa.getBoundingClientRect();
      mira.style.left = (p0.left - c.left + dados.frações[i] * p0.width) + 'px';
      mira.style.display = 'block';
      hora.textContent = dados.rótulos[i];
      for (const p of plots) {
        const id = p.parentElement.dataset.trilha;
        const t = dados.trilhas[id];
        t.séries.forEach((valores, k) => {
          const v = valores[i];
          const m = p.querySelector('.marcador.s' + (k + 1));
          if (v == null) m.style.display = 'none';
          else Object.assign(m.style, { display: 'block', left: (dados.frações[i] * 100) + '%', bottom: (v / t.topo * 100) + '%' });
          document.querySelector('[data-valor="' + id + '-' + k + '"]').textContent = fmt(v, t.unidade);
        });
      }
    };
    const esconder = () => {
      atual = null;
      mira.style.display = 'none';
      hora.textContent = dados.agora;
      for (const p of plots) {
        const id = p.parentElement.dataset.trilha;
        const t = dados.trilhas[id];
        t.séries.forEach((valores, k) => {
          p.querySelector('.marcador.s' + (k + 1)).style.display = 'none';
          let j = valores.length - 1;
          while (j >= 0 && valores[j] == null) j--;
          document.querySelector('[data-valor="' + id + '-' + k + '"]').textContent = fmt(valores[j], t.unidade);
        });
      }
    };
    for (const p of plots) {
      p.addEventListener('pointermove', e => {
        const r = p.getBoundingClientRect();
        mostrar(maisPerto((e.clientX - r.left) / r.width));
      });
      p.addEventListener('pointerleave', esconder);
    }
    // pelo teclado, a coleta inteira é lida em voz: a hora e todas as séries
    const leitura = document.querySelector('[data-leitura]');
    const nomes = [...caixa.querySelectorAll('.trilha')].map(t => [...t.querySelectorAll('.nome')].map(e => e.textContent));
    caixa.addEventListener('keydown', e => {
      if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
      e.preventDefault();
      const i = Math.max(0, Math.min(n - 1, (atual ?? n - 1) + (e.key === 'ArrowLeft' ? -1 : 1)));
      mostrar(i);
      leitura.textContent = dados.rótulos[i] + ': ' + Object.values(dados.trilhas).map((t, j) =>
        t.séries.map((valores, k) => nomes[j][k] + ' ' + fmt(valores[i], t.unidade)).join(', ')).join('; ');
    });
    caixa.addEventListener('blur', esconder);
  })();
</script>`}
</div>
</body>
</html>`;

return [{ json: { html } }];
